//! Checks of the downside objectives (minimum semivariance and CDaR), the floor on expected
//! return and the smallest effective number of assets against problems formulated
//! independently in CVXPY. The fixture is generated by
//! `scripts/reference/downside_objectives.py`.

#![allow(clippy::unwrap_used)]

use finalytics_opt::*;
use finalytics_risk::{Matrix, ReturnsTable};
use serde_json::Value;

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

#[test]
fn downside_objectives_match_the_reference() {
    let fixture: Value = serde_json::from_str(include_str!("fixtures/downside.json")).unwrap();
    let names: Vec<String> = serde_json::from_value(fixture["labels"].clone()).unwrap();
    let columns = fixture["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .map(floats)
        .collect();
    let base = Problem::from_covariance(
        Matrix::new(names.clone(), floats(&fixture["covariance"])).unwrap(),
    )
    .with_expected_returns(floats(&fixture["expected_returns"]))
    .with_scenarios(ReturnsTable::new(names, columns).unwrap());
    for case in fixture["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let objective: Objective = serde_json::from_value(case["problem"].clone()).unwrap();
        let constraints: Constraints = serde_json::from_value(case["constraints"].clone()).unwrap();
        let solution = base
            .clone()
            .with_constraints(constraints)
            .solve(&objective)
            .unwrap();
        assert_eq!(solution.status, SolveStatus::Optimal, "{name}");
        assert!(
            solution.max_violation.unwrap() < 1e-7,
            "{name}: {:?}",
            solution.max_violation
        );
        let value = solution.objective_value.unwrap();
        let reference = case["objective_value"].as_f64().unwrap();
        assert!(
            (value - reference).abs() <= 1e-7 * reference.abs().max(1.0),
            "{name}: objective {value} against the reference {reference}"
        );
        // A linear programme can have many optimal portfolios, so only its objective is
        // compared.
        if !case["unique"].as_bool().unwrap() {
            continue;
        }
        let weights = solution.weights.unwrap();
        for (k, (w, r)) in weights.iter().zip(floats(&case["weights"])).enumerate() {
            assert!(
                (w - r).abs() < 2e-5,
                "{name}: weight {k} is {w}, the reference {r}"
            );
        }
    }
}

#[test]
fn the_new_limits_are_checked() {
    let labels: Vec<String> = ["a", "b", "c"].map(str::to_owned).to_vec();
    let covariance = Matrix::new(
        labels.clone(),
        vec![0.04, 0.0, 0.0, 0.0, 0.09, 0.0, 0.0, 0.0, 0.16],
    )
    .unwrap();
    let mut constraints = Constraints::default();
    constraints.min_effective_assets = Some(4.0);
    constraints.min_return = Some(f64::NAN);
    let error = Problem::from_covariance(covariance.clone())
        .with_constraints(constraints)
        .solve(&Objective::MinimumVariance)
        .unwrap_err();
    let text = error.to_string();
    assert!(
        text.contains("constraints.min_effective_assets")
            && text.contains("constraints.min_return")
            && text.contains("expected_returns"),
        "{text}"
    );

    // A floor no portfolio reaches leaves the problem without a solution.
    let mut constraints = Constraints::default();
    constraints.min_return = Some(0.2);
    let solution = Problem::from_covariance(covariance)
        .with_expected_returns(vec![0.05, 0.08, 0.1])
        .with_constraints(constraints)
        .solve(&Objective::MinimumVariance)
        .unwrap();
    assert_eq!(solution.status, SolveStatus::Infeasible);

    // The downside objectives need scenarios.
    let problem = Problem::from_covariance(
        Matrix::new(labels, vec![0.04, 0.0, 0.0, 0.0, 0.09, 0.0, 0.0, 0.0, 0.16]).unwrap(),
    );
    for objective in [
        Objective::MinimumSemivariance,
        Objective::MinimumCdar { confidence: 0.95 },
    ] {
        let text = problem.solve(&objective).unwrap_err().to_string();
        assert!(text.contains("scenarios"), "{text}");
    }
}
